import unittest
from checkout import can_checkout

class CheckoutTests(unittest.TestCase):
    def test_more_than_cost(self):
        self.assertTrue(can_checkout(11, 10))

    def test_less_than_cost(self):
        self.assertFalse(can_checkout(9, 10))

    def test_exact_cost(self):
        self.assertTrue(can_checkout(10, 10))

